CREATE DATABASE IF NOT EXISTS linguax CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci; USE linguax;
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL DEFAULT '',password_hash VARCHAR(255) NOT NULL,status ENUM('active','blocked') NOT NULL DEFAULT 'active',trial_started_at DATETIME NULL,trial_used_seconds INT UNSIGNED NOT NULL DEFAULT 0,plan ENUM('free','pro') NOT NULL DEFAULT 'free',plan_expires_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE translations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,source_lang VARCHAR(20) NOT NULL,target_lang VARCHAR(20) NOT NULL,input_text TEXT NOT NULL,output_text MEDIUMTEXT NOT NULL,provider VARCHAR(50) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(user_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE orders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,order_no VARCHAR(64) NOT NULL UNIQUE,amount DECIMAL(10,2) NOT NULL,status ENUM('pending','paid','cancelled','refunded') NOT NULL DEFAULT 'pending',provider VARCHAR(40) NOT NULL DEFAULT 'manual',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,paid_at DATETIME NULL,INDEX(user_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE ads(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,slot VARCHAR(50) NOT NULL,title VARCHAR(150) NOT NULL,html_code TEXT NOT NULL,enabled TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE settings(`key` VARCHAR(80) PRIMARY KEY,value TEXT NOT NULL) ENGINE=InnoDB;
